contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address[] calldata governables, bool[] calldata isGoverned) public {
        require(governables.length == isGoverned.length && governables.length > 0);

        uint256 len = governables.length;

        // Ensure DAO has an active successful proposal for this test contract.
        // We assume LimboDAOLike(DAO).successfulProposal(address(this)) is already true.
        // Given the deployment is fresh and run once, we cannot set that up here,
        // but the property is meant to hold when the call succeeds; we test the
        // observable state change for one representative governed address.
        address target = governables[0];
        bool expected = isGoverned[0];

        c.setGoverned(governables, isGoverned);

        assert(c.governed(target) == expected);
    }
}

