        c = _c;
    }

    function run(address newDao, address caller, bool doEndConfiguration) public {
        if (doEndConfiguration) {
            c.endConfiguration();
        }

        address oldDao = c.DAO();
        bool configuredBefore = c.configured();
        bool succeeds = oldDao == address(0) || caller == oldDao || !configuredBefore;

