contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bool enforce, uint256 v1, uint256 v2) public {
        require(v1 <= type(uint128).max && v2 <= type(uint128).max);
        if (enforce) {
            c.setEnforcement(true);
            (bool ok) = address(c).call(abi.encodeWithSignature("enforceTolerance(uint256,uint256)", v1, v2));
            assert(ok || c.configured() == false || !isConfigured());
        } else {
            c.setEnforcement(false);
            (bool ok) = address(c).call(abi.encodeWithSignature("enforceTolerance(uint256,uint256)", v1, v2));
            assert(ok);
        }
    }

    function isConfigured() internal view returns (bool) {
        return c.governer() != address(0);
    }

    receive() external payable {}
}

