// Minimal ERC20 used only to provide a token for C's flash governance config.
contract FakeERC20 {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function mint(address to, uint256 amount) external { balanceOf[to] += amount; }
    function approve(address spender, uint256 amount) external returns (bool) { allowance[msg.sender][spender] = amount; return true; }
    function transfer(address to, uint256 amount) external returns (bool) { balanceOf[msg.sender] -= amount; balanceOf[to] += amount; return true; }
    function transferFrom(address from, address to, uint256 amount) external returns (bool) { allowance[from][msg.sender] -= amount; balanceOf[from] -= amount; balanceOf[to] += amount; return true; }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(
        address tokenAddr,
        address governanceSender,
        address target,
        uint256 assetAmount,
        uint256 unlockTimeSeconds
    ) public payable {
        require(tokenAddr != address(0), "zero token");
        require(governanceSender != address(0), "zero sender");
        require(target != address(0), "zero target");
        require(assetAmount > 0, "zero amount");
        require(unlockTimeSeconds > 0, "zero unlock");

        // Configure C so that this contract is a governed caller and can call assertGovernanceApproved.
        address[] memory governables = new address[](1);
        governables[0] = address(this);
        bool[] memory isGoverned = new bool[](1);
        isGoverned[0] = true;
        c.setGoverned(governables, isGoverned);

        // Configure the flash governance asset/amount/unlock for the call.
        c.configureFlashGovernance(tokenAddr, assetAmount, unlockTimeSeconds, false);

        // Ensure this contract has enough tokens for the transferFrom in assertGovernanceApproved.
        require(
            IERC20(tokenAddr).balanceOf(address(this)) >= assetAmount,
            "insufficient token balance"
        );
        IERC20(tokenAddr).approve(address(c), assetAmount);

        bool reverted;
        try c.assertGovernanceApproved(governanceSender, target, false) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            (, uint256 unlockTimeAfter, address assetAfter, bool burnableAfter) =
                c.pendingFlashDecision(target, governanceSender);
            assert(
                assetAfter == tokenAddr &&
                burnableAfter == false &&
                unlockTimeAfter == block.timestamp + unlockTimeSeconds
            );
        } else {
            assert(true);
        }
    }

    receive() external payable {}
}

