    }

    function run(
        address asset,
        uint256 amount,
        uint256 unlockTime,
        bool assetBurnable
    ) public payable {
        require(asset != address(0));

        uint256 beforeAssetBalance = IERC20(asset).balanceOf(address(this));

        (uint256 beforeAmount, uint256 beforeUnlockTime, address beforeAsset, bool beforeBurnable) = c.flashGovernanceConfig();

        bool reverted;
        try c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint256 afterAmount, uint256 afterUnlockTime, address afterAsset, bool afterBurnable) = c.flashGovernanceConfig();
        uint256 afterAssetBalance = IERC20(asset).balanceOf(address(this));

        assert(
            afterAssetBalance == beforeAssetBalance &&
            (
                reverted
                    ? (afterAmount == beforeAmount &&
                       afterUnlockTime == beforeUnlockTime &&
                       afterAsset == beforeAsset &&
                       afterBurnable == beforeBurnable)
                    : true
            )
        );
    }

    receive() external payable {}
}

