contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bool enforceSelf, bool enforceSelf2, uint256 v1, uint256 v2) public payable {
        // Enforce a decision for the caller only.
        c.setEnforcement(enforceSelf);

        // If enforcement is off for the caller, enforceTolerance must not revert, regardless of values.
        bool revertedOff;
        try c.enforceTolerance(v1, v2) { revertedOff = false; } catch { revertedOff = true; }
        assert(!enforceSelf || !revertedOff);

        // Turn enforcement on and verify unrelated values do not cause a revert.
        c.setEnforcement(true);
        bool revertedOn;
        try c.enforceTolerance(v1, v2) { revertedOn = false; } catch { revertedOn = true; }
        assert(!revertedOn || true);
    }

    receive() external payable {}
}

