contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint8 selector, uint256 v1, uint256 v2) public payable {
        address me = address(this);
        address other = address(uint160(uint256(keccak256(abi.encode(me, selector)))) | 1);

        // Ensure the state we are about to observe is well-defined for this test address
        // by making an initial call through the public mutating function.
        c.setEnforcement(selector % 2 == 0);

        // Capture before values using only public observable surface.
        // setEnforcement is the only function that changes enforceLimitsActive;
        // observe its effect through revert behavior of enforceTolerance.
        bool beforeMeReverts;
        try c.enforceTolerance(v1, v2) {
            beforeMeReverts = false;
        } catch {
            beforeMeReverts = true;
        }

        bool reverted;
        try c.enforceTolerance(v1, v2) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(beforeMeReverts == reverted);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bool enforce, uint256 v1, uint256 v2) public payable {
        address me = address(this);

        c.setEnforcement(enforce);

        bool afterReverts;
        try c.enforceTolerance(v1, v2) {
            afterReverts = false;
        } catch {
            afterReverts = true;
        }

        bool expectedRevert;
        if (!enforce) {
            expectedRevert = false;
        } else {
            // When enforcement is active, the only way enforceTolerance can return
            // without reverting is when the relative deviation stays below the
            // configured tolerance. changeTolerance is zero by default in a fresh C,
            // so any call with enforcement active should revert here (since neither
            // the DAO nor this test contract has configured changeTolerance above 0).
            expectedRevert = true;
        }

        assert(afterReverts == expectedRevert);
    }

    receive() external payable {}
}

