contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bool enforce, uint256 v1, uint256 v2) public {
        // Read the original flag for this contract (the caller) before any state change.
        bool before = c.enforceLimitsActive(address(this));

        // Change the flag through the public surface.
        c.setEnforcement(enforce);

        // Read the new flag for this contract.
        bool after = c.enforceLimitsActive(address(this));

        // The setter must set exactly the requested value for the caller.
        assert(after == enforce && after != before || after == before);

        // A separate general rule: enforceTolerance must not revert when the caller's flag is false.
        bool reverted = false;
        if (!after) {
            try c.enforceTolerance(v1, v2) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }
        assert(!(!after && reverted));
    }
}

