contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(
        address[] calldata governables,
        bool[] calldata isGoverned,
        address targetContract,
        address user,
        address asset,
        uint256 amount,
        address newDAO,
        bool enforce
    ) public {
        // Setup: c is fresh and unconfigured (DAO set to constructor arg, configured == false).
        // The test contract is the msg.sender of every call on c, and the test deployed c,
        // hence msg.sender != DAO (DAO is the address passed to c's constructor at deployment).

        // Observe relevant starting state through public getters only.
        bool configuredBefore = c.configured();
        address daoBefore = c.DAO();

        // Attempt a gated state-changing call; it should revert unless configured or msg.sender == DAO.
        bool setGovernedReverted;
        try c.setGoverned(governables, isGoverned) {
            setGovernedReverted = false;
        } catch {
            setGovernedReverted = true;
        }

        bool configureFlashReverted;
        try c.configureFlashGovernance(asset, amount, block.timestamp + 1, true) {
            configureFlashReverted = false;
        } catch {
            configureFlashReverted = true;
        }

        bool configureSecurityReverted;
        try c.configureSecurityParameters(1, 1, 1) {
            configureSecurityReverted = false;
        } catch {
            configureSecurityReverted = true;
        }

        bool burnAssetReverted;
        try c.burnFlashGovernanceAsset(targetContract, user, asset, amount) {
            burnAssetReverted = false;
        } catch {
            burnAssetReverted = true;
        }

        // Non-gated state-changing calls should succeed.
        c.setEnforcement(enforce);
        c.setDAO(newDAO);

        // Read back observable effects.
        bool enforcedAfter = c.enforceLimitsActive(address(this));
        address daoAfter = c.DAO();

        // General rule: When c is unconfigured, the onlySuccessfulProposal-gated functions revert,
        // while the permissionless setEnforcement and DAO updates behave as specified.
        assert(
            (configuredBefore || setGovernedReverted) &&
            (configuredBefore || configureFlashReverted) &&
            (configuredBefore || configureSecurityReverted) &&
            (configuredBefore || burnAssetReverted) &&
            enforcedAfter == enforce &&
            daoAfter == newDAO
        );
    }
}

