contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target, address sender, uint256 amount, uint256 unlockTime, bool assetBurnable) public payable {
        // Setup: choose a governance asset (this test contract's address needs no real ERC20 here).
        // We only exercise the state-machine storage path, so use the caller as asset and
        // ensure the transferFrom call has a chance to succeed by mocking nothing.
        address asset = address(this);

        // Make this test contract a governed caller so flashEnabled passes.
        address[] memory governables = new address[](1);
        governables[0] = address(this);
        bool[] memory isGoverned = new bool[](1);
        isGoverned[0] = true;

        // Configure flash governance.
        c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable);
        c.setGoverned(governables, isGoverned);

        // Record before state.
        uint256 pendingAmountBefore = c.pendingFlashDecision(target, sender).amount;

        // Attempt the deciding call. It will revert because asset transferFrom will fail
        // (this contract is not an ERC20), which is the expected path for a non-ERC20 asset.
        bool reverted;
        try c.assertGovernanceApproved(sender, target, false) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: if the call did not revert, the pending decision stores exactly
        // the configured amount, and the caller (this test contract) transferred that amount
        // into c. If it reverted, no pending decision was created/changed.
        uint256 pendingAmountAfter = c.pendingFlashDecision(target, sender).amount;

        if (!reverted) {
            assert(pendingAmountAfter == amount && address(c).balance == amount);
        } else {
            assert(pendingAmountAfter == pendingAmountBefore);
        }
    }

    receive() external payable {}
}

