contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address asset, uint256 amount, uint256 unlockTime, bool assetBurnable, address target) public payable {
        require(unlockTime > 0);

        c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable);

        (address cfgAsset, uint256 cfgAmount, uint256 cfgUnlock, bool cfgBurnable) = c.flashGovernanceConfig();
        require(cfgAsset == asset && cfgAmount == amount && cfgBurnable == assetBurnable);

        (address a1, uint256 am1, uint256 u1, bool b1) = c.pendingFlashDecision(target, address(this));
        require(am1 == 0);

        uint256 balBefore = address(this).balance;

        // Wait until unlock time passes so the pending decision is withdrawable.
        // We cannot warp, so require that the test was invoked with a large enough block context:
        // unlockTime is chosen by the caller to be small enough relative to block.timestamp.
        require(unlockTime > 0 && unlockTime <= block.timestamp);

        // Withdraw path requires a pending decision, so first set one via assertGovernanceApproved.
        // Use this contract as both sender and target so that the pending entry keyed by (target, address(this)) exists.
        // The deposit asset is not this contract's token; we only test the withdrawal of the recorded amount.
        c.setGoverned(new address[](0), new bool[](0));

        // Read-only checks before deciding call:
        (address a2, uint256 am2) = _pendingAmount(target, address(this));

        // The deciding call: withdraw governance asset for target and sender = address(this).
        bool reverted;
        try c.withdrawGovernanceAsset(target, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            (address a3, uint256 am3, uint256 u3, bool b3) = c.pendingFlashDecision(target, address(this));
            assert(am3 == 0);
        } else {
            assert(reverted);
        }
    }

    function _pendingAmount(address target, address sender) internal view returns (address, uint256) {
        (address a, uint256 am, uint256 u, bool b) = c.pendingFlashDecision(target, sender);
        return (a, am);
    }

    receive() external payable {}
}

