    ) public {
        require(target != address(0));
        require(user != address(0));
        require(asset != address(0));
        require(amount > 0);

        // Drive the public surface: set the flash governance config (onlySuccessfulProposal
        // is bypassed because c.configured() is false right after deployment).
        c.configureFlashGovernance(asset, amount, unlockTime, false);

        // Read the before values through the public getter of pendingFlashDecision.
        (uint256 beforeAmount, uint256 beforeUnlock, address beforeAsset, ) =
            c.pendingFlashDecision(target, user);

        // A fresh c has no pending decision for this (target, user) unless the config
        // getter returned the zero-valued struct.  Only assert the general rule when a
        // pending decision actually exists (beforeAmount > 0), which is exactly the
        // intended path that withdrawGovernanceAsset must guard.
        bool reverted;
        if (beforeAmount > 0) {
            try c.withdrawGovernanceAsset(target, asset) {
                reverted = false;
            } catch {
                reverted = true;
            }

            if (beforeUnlock < block.timestamp) {
                // After a successful withdrawal the pending record must be cleared.
                (uint256 afterAmount, , , ) = c.pendingFlashDecision(target, user);
                assert(!reverted && afterAmount == 0);
            } else {
                // Still locked: the guard must reject, so the record stays intact.
                (uint256 afterAmount, uint256 afterUnlock, , ) =
                    c.pendingFlashDecision(target, user);
                assert(reverted && afterAmount == beforeAmount && afterUnlock == beforeUnlock);
            }
        } else {
            // No pending decision exists: the call must revert rather than succeed.
            try c.withdrawGovernanceAsset(target, asset) {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(reverted);
        }
    }

    receive() external payable {}
}

