contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address asset,
        address targetContract,
        address user,
        uint256 amount,
        uint256 unlockTime,
        bool assetBurnable
    ) public payable {
        require(user != address(0));
        require(targetContract != address(0));
        require(asset != address(0));

        c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable);

        // Record the pending decision for (targetContract, user) by acting as the DAO
        // through the public assertGovernanceApproved entry point.
        c.assertGovernanceApproved(user, targetContract, true);

        // Advance past the unlock time by reusing the public config.
        // We read the pending entry only through the public getter.
        (uint256 recordedAmount, uint256 recordedUnlockTime, address recordedAsset, bool recordedBurnable) =
            c.pendingFlashDecision(targetContract, user);

        // Ensure the recorded decision is withdrawable by making time pass via the
        // public withdraw path only when unlocked. If not yet unlocked, skip the
        // withdrawal assertion by restoring the state through burnFlashGovernanceAsset.
        bool unlocked = recordedUnlockTime < block.timestamp;

        if (unlocked) {
            bool revertedFirst;
            try c.withdrawGovernanceAsset(targetContract, asset) {
                revertedFirst = false;
            } catch {
                revertedFirst = true;
            }

            bool revertedSecond;
            try c.withdrawGovernanceAsset(targetContract, asset) {
                revertedSecond = false;
            } catch {
                revertedSecond = true;
            }

            // General rule: a withdrawable decision can be withdrawn once, and the
            // second withdrawal of the same (targetContract, sender) pair must revert
            // because the pending decision was deleted.
            assert(!revertedFirst && revertedSecond);
        } else {
            // Not unlocked yet: the withdrawal must revert and the pending decision
            // must still be recorded with the configured values.
            bool revertedFirst;
            try c.withdrawGovernanceAsset(targetContract, asset) {
                revertedFirst = false;
            } catch {
                revertedFirst = true;
            }

            (uint256 afterAmount, uint256 afterUnlockTime, address afterAsset, bool afterBurnable) =
                c.pendingFlashDecision(targetContract, user);

            assert(
                revertedFirst &&
                afterAmount == amount &&
                afterUnlockTime == recordedUnlockTime &&
                afterAsset == asset &&
                afterBurnable == assetBurnable
            );
        }
    }

    receive() external payable {}
}

