contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address asset,
        uint256 amount,
        uint256 unlockTime,
        bool assetBurnable,
        address target,
        address sender,
        bool emergency
    ) public {
        uint256 setupAmount = 1;
        uint64 setupUnlock = 0;
        address setupAsset = address(0);
        bool setupBurnable = false;

        // Reset configuration to a known baseline via the onlySuccessfulProposal path is not possible
        // (no successful proposal in a fresh instance unless DAO is configured), so use the direct
        // onlySuccessfulProposal call which succeeds when !configured.
        c.configureFlashGovernance(setupAsset, setupAmount, setupUnlock, setupBurnable);

        // Reconfigure to the parameters of interest.
        c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable);

        (uint256 gotAmount, uint256 gotUnlockTime, address gotAsset, bool gotAssetBurnable) = c.flashGovernanceConfig();

        // Snapshot pending before the deciding call for the target/sender pair.
        (uint256 beforeAmount, uint256 beforeUnlockTime, address beforeAsset, bool beforeBurnable) = c.pendingFlashDecision(target, sender);

        bool reverted;
        try c.assertGovernanceApproved(sender, target, emergency) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint256 afterAmount, uint256 afterUnlockTime, address afterAsset, bool afterBurnable) = c.pendingFlashDecision(target, sender);

        // General rule: configureFlashGovernance stores the exact parameters in c.flashGovernanceConfig,
        // and when assertGovernanceApproved does not revert it records the configured amount in the
        // pending decision for (target, sender); when it reverts, the pending entry for the target is
        // left untouched.
        if (!reverted) {
            assert(
                gotAsset == asset &&
                gotAmount == amount &&
                gotUnlockTime == unlockTime &&
                gotAssetBurnable == assetBurnable &&
                afterAmount == amount &&
                afterAsset == asset
            );
        } else {
            assert(
                gotAsset == asset &&
                gotAmount == amount &&
                gotUnlockTime == unlockTime &&
                gotAssetBurnable == assetBurnable &&
                afterAmount == beforeAmount &&
                afterUnlockTime == beforeUnlockTime &&
                afterAsset == beforeAsset &&
                afterBurnable == beforeBurnable
            );
        }
    }
}

