        bool after0 = c.governed(a);
        bool after1 = c.governed(b);

        // General rule: a length-mismatched setGoverned call always reverts and cannot mutate governed state.
        assert(reverted && after0 == before0 && after1 == before1);
    }

    receive() external payable {}
}

