contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    receive() external payable {}

    function run(
        address asset,
        uint256 amount,
        uint256 unlockTime,
        address target,
        bool emergency
    ) public payable {
        require(address(this).balance >= amount, "insufficient balance");

        // Configure the flash governance parameters with values we control.
        c.configureFlashGovernance(asset, amount, unlockTime, false);

        // Snapshot the public configuration before the deciding call.
        (uint256 beforeAmount, uint256 beforeUnlockTime, address beforeAsset, bool beforeBurnable) = c.flashGovernanceConfig();

        // Make the deciding call. It either succeeds or reverts.
        // The call must be a top-level statement.
        bool reverted;
        try c.assertGovernanceApproved(address(this), target, emergency) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read the resulting configuration after the call.
        (uint256 afterAmount, uint256 afterUnlockTime, address afterAsset, bool afterBurnable) = c.flashGovernanceConfig();

        // General rule: the configuration of flashGovernanceConfig is never modified by
        // assertGovernanceApproved; it can only be set by configureFlashGovernance.
        assert(
            !reverted
                ? (afterAmount == beforeAmount &&
                   afterUnlockTime == beforeUnlockTime &&
                   afterAsset == beforeAsset &&
                   afterBurnable == beforeBurnable)
                : (afterAmount == beforeAmount &&
                   afterUnlockTime == beforeUnlockTime &&
                   afterAsset == beforeAsset &&
                   afterBurnable == beforeBurnable)
        );
    }
}

