contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(
        address daoLike,
        address target,
        uint256 amount,
        address asset,
        uint256 unlockTime,
        bool assetBurnable,
        bool emergency
    ) public payable {
        require(amount > 0, "amount must be positive");

        // Set up the DAO/govterner infrastructure so that onlySuccessfulProposal and flashEnabled pass.
        // Deploy minimal stub contracts in-place using assembly would be complex; instead use the
        // existing C surface: setDAO and configureFlashGovernance (onlySuccessfulProposal).
        // We need the DAO to be a contract that returns successfulProposal == true and provides
        // getFlashGoverner. Since we cannot define new contracts, we use the provided DAO-like
        // and FlashGovernanceArbiterLike abstract contracts? They are abstract and cannot be deployed.
        // Therefore, we focus on the rule achievable purely with c's own surface and constructor DAO.

        // The only calls on c that can be made without a successful proposal are:
        // setDAO (if !configured), setEnforcement, enforceTolerance*, withdrawGovernanceAsset,
        // and assertGovernanceApproved (if msg.sender is DAO or governed, and DAO must be set).

        // We can use setDAO to set DAO to an arbitrary address, but that address must implement
        // successfulProposal and getFlashGoverner for _governanceApproved to work. However,
        // configureFlashGovernance requires onlySuccessfulProposal: assertSuccessfulProposal(sender)
        // which calls LimboDAOLike(DAO).successfulProposal(sender) if configured.
        // Since c is fresh and configured == false? Actually Governable constructor sets configured = false.
        // configured is inherited public from Configurable? Not exactly: C inherits Governable, which
        // has bool public configured. So c.configured() returns false initially.
        // In onlySuccessfulProposal, assertSuccessfulProposal: require(!configured || successfulProposal(sender)).
        // Since configured == false, the require passes for any sender. So we can call
        // configureFlashGovernance directly without a DAO call!

        // Similarly, setGoverned works.

        // So the plan:
        // 1. Configure flash governance with given asset, amount, unlockTime, assetBurnable.
        //    This call will succeed because configured == false.
        // 2. Call assertGovernanceApproved(target, sender?, emergency) -- but this is called on c
        //    by an external address, and it checks msg.sender == DAO || governed[msg.sender].
        //    Our test contract is msg.sender for all calls. We need msg.sender (the test contract)
        //    to be either DAO or governed. We can set DAO to address(this) via setDAO, or
        //    set governed[address(this)] = true via setGoverned (which requires onlySuccessfulProposal,
        //    but configured is false so it passes).

        // Let's set governed[address(this)] = true.
        address[] memory governables = new address[](1);
        governables[0] = address(this);
        bool[] memory isGoverned = new bool[](1);
        isGoverned[0] = true;
        c.setGoverned(governables, isGoverned);

        // Now configure flash governance.
        c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable);

        // Read back configured values.
        (uint256 cfgAmount, uint256 cfgUnlockTime, address cfgAsset, bool cfgAssetBurnable) = c.flashGovernanceConfig();

        // The target for the flash decision: we use an arbitrary address parameter.
        address sender = address(this);

        // Now call assertGovernanceApproved. This will attempt IERC20(asset).transferFrom(sender, address(this), amount).
        // If asset is not a real ERC20 or the call fails, the whole transaction reverts. To avoid that,
        // we need asset to be a token that allows transferFrom. But we cannot deploy a token contract.
        // However, the rule we want to test can abstract over successful transferFrom by focusing on
        // the case where transferFrom succeeds. Since we can't guarantee that without a token,
        // we instead test the storage update rule assuming the transfer succeeds.
        // We can use address(0) as asset? transferFrom on address(0) will revert.

        // Alternative: focus on the configuration rule itself, which is directly observable and
        // does NOT require a successful governance approval.
        // The rule: after configureFlashGovernance, the public getter flashGovernanceConfig returns
        // exactly the values passed in, EXCEPT that unlockTime is NOT adjusted here -- actually
        // configureFlashGovernance sets flashGovernanceConfig fields directly.
        // So assert that flashGovernanceConfig matches the parameters.

        assert(
            cfgAmount == amount &&
            cfgUnlockTime == unlockTime &&
            cfgAsset == asset &&
            cfgAssetBurnable == assetBurnable
        );
    }

    receive() external payable {}
}

