contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address dao, address target, bool emergency) public payable {
        // Ensure DAO and caller setup: the only caller that can succeed without being governed is the DAO.
        // We test the general rule that a non-DAO, non-governed caller must revert with the flashEnabled guard.
        c.setDAO(dao);
        // Read before state (governed for current sender is false unless set by proposal; we can't set here)
        bool governedBefore = c.governed(address(this));
        // snapshot pending flash decision for target and this caller
        (uint256 amountBefore, uint256 unlockBefore, address assetBefore, bool burnableBefore) = c.pendingFlashDecision(target, address(this));

        bool reverted;
        try c.assertGovernanceApproved(address(this), target, emergency) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After state
        (uint256 amountAfter, uint256 unlockAfter, address assetAfter, bool burnableAfter) = c.pendingFlashDecision(target, address(this));

        // General rule: if caller is not DAO and not governed, the call must revert.
        // If it succeeds, the pending decision unlockTime must have been extended.
        // Also, on revert, the pending decision must remain unchanged.
        bool shouldSucceed = (msg.sender == dao) || governedBefore;
        if (shouldSucceed) {
            // If it succeeded, the unlock time must be >= block.timestamp (since it's extended by block.timestamp)
            assert(!reverted ? unlockAfter >= block.timestamp : true);
        } else {
            // Caller is not DAO and not governed: must revert
            assert(reverted);
            // And pending decision must be unchanged
            assert(unlockAfter == unlockBefore && amountAfter == amountBefore && assetAfter == assetBefore && burnableAfter == burnableBefore);
        }
    }

    receive() external payable {}
}

