    }

    function run(address sender, bool enforce, int256 v1, int256 v2) public payable {
        require(sender != address(0), "zero sender");

        // Record whether sender is currently governed and configured through public surface only.
        // We read c.enforceToleranceInt before/after as the observable effect.

        bool beforeReverts;
        try c.enforceToleranceInt(v1, v2) {
            beforeReverts = false;
        } catch {
            beforeReverts = true;
        }

        c.setEnforcement(enforce);

        bool afterReverts;
        try c.enforceToleranceInt(v1, v2) {
            afterReverts = false;
        } catch {
            afterReverts = true;
        }

        // setEnforcement on c is called by this test contract, so it affects c.enforceLimitsActive[address(this)].
        // enforceLimitsActive is public and has a getter: c.enforceLimitsActive(address(this))
        bool active = c.enforceLimitsActive(address(this));

        // The general rule: after calling setEnforcement(enforce), the public flag for the caller equals enforce,
        // and enforceToleranceInt's revert behavior is unchanged unless the flag became true and the limits are active for a configured sender.
        // Since sender is this test contract, active == enforce.
        assert(active == enforce);
    }

    receive() external payable {}
}

