contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target, address user) public {
        // Read the current flash governance configuration (public getter).
        (uint256 cfgAmount, uint256 cfgUnlock, address cfgAsset, ) = c.flashGovernanceConfig();

        // Snapshot the pending decision before the call (public getter).
        (uint256 beforeAmount, uint256 beforeUnlock, address beforeAsset, bool beforeBurnable) =
            c.pendingFlashDecision(target, user);

        // The rule only makes sense when no prior pending decision exists; otherwise
        // the unlockTime assignment is not deterministic from a single fresh call.
        require(beforeAsset == address(0) && beforeAmount == 0 && beforeUnlock == 0 && !beforeBurnable);

        // Drive the state-changing call. This may revert, e.g. when the token
        // transferFrom fails because the test contract holds no tokens.
        bool reverted;
        try c.assertGovernanceApproved(user, target, true) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            (uint256 afterAmount, uint256 afterUnlock, address afterAsset, bool afterBurnable) =
                c.pendingFlashDecision(target, user);
            assert(
                afterAmount == cfgAmount &&
                afterAsset == cfgAsset &&
                afterBurnable == (c.flashGovernanceConfig(), 0)
            );
        }
    }

    receive() external payable {}
}

