contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address target, bool emergency) public payable {
        // caller must not be the DAO and must not be governed
        address dao = c.DAO();
        require(caller != dao, "caller is DAO");
        require(!c.governed(caller), "caller is governed");

        // ensure asset is set to a usable ERC20 (if not, the require on transferFrom will revert anyway,
        // but we want the rule to hold for any reachable state; we don't set it because we cannot
        // be sure to have a successful proposal, so we just test the modifier's guard).
        bool reverted;
        try c.assertGovernanceApproved(caller, target, emergency) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted);
    }
}

